<label><span>A<sub>z</sub> (height, up) = <b id="vaz">2.5</b></span>
  <input id="saz" type="range" min="0" max="3" step="0.1" value="2.5">
</label>
<div id="magOut" style="font-family:ui-monospace,Consolas,monospace;margin-top:2px">|A| = 4.39</div>
<div style="color:#666;font-size:10.5px;line-height:1.3">|A| = √(A<sub>x</sub>² + A<sub>y</sub>² + A<sub>z</sub>²)</div>

<div style="margin-top:5px">Construction</div>
