  <input id="chkTri" type="checkbox"> show |A| right triangles (extra)
</label>

<div style="margin-top:6px;border-top:1px solid #dcdfe3;padding-top:5px">
  <div style="display:flex;gap:4px;align-items:center">
    <button id="btnPrev">◀</button>
    <button id="btnNext">▶</button>
    <span id="stepNum" style="font-size:11px;color:#555">step 3/4</span>
  </div>
  <div id="stepTitle" style="font-weight:600;margin-top:4px"></div>
  <div id="stepNarr" style="white-space:normal;line-height:1.35;color:#333"></div>
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec ───────────────────────────────────────────────────────────
   x-axis (world +Z, recedes lower-left) → thin Line black + ConeGeometry head, italic 'x'
   y-axis (world +X, to the right)       → thin Line black + Cone head, italic 'y'
   z-axis (world +Y, straight up)        → thin Line black + Cone head, italic 'z'
   dashed box (12 edges)                 → LineSegments + LineDashedMaterial grey #7f7f7f
   optional |A| right triangles          → LineSegments + LineDashedMaterial (off by default)
   A_x arrow  → Group[Cylinder r0.045 + Cone r0.105] navy #1F4E79 along +Z(world)
   A_y arrow  → Group[Cylinder + Cone] navy along +X(world)
   A_z arrow  → Group[Cylinder + Cone] navy along +Y(world)
   A  arrow   → Group[Cylinder r0.048 + Cone r0.115] red #C0392B, body diagonal, renderOrder 3
   corner flash marker → SphereGeometry(0.09) red, pulsed when the chain closes
   all text   → addLabel HTML (overline = vector arrow, î ĵ k̂ hats), rotated along its arrow
   NOTE: cone head LENGTH is foreshortening-compensated every frame so a head
         aimed at the camera still projects as a triangle, never a disc/sphere.
   ────────────────────────────────────────────────────────────────────────── */

const BLUE = 0x1F4E79, RED = 0xC0392B, GREY = 0x7f7f7f, GREY2 = 0x666666, BLACK = 0x1a1a1a;
const V = (x, y, z) => new THREE.Vector3(x, y, z);
// world mapping: A_x -> world Z (toward viewer), A_y -> world X (right), A_z -> world Y (up)
const W3 = (ax, ay, az) => V(ay, az, ax);

const state = { ax: 2.0, ay: 3.0, az: 2.5, mode: 'edges', tri: false, buildT: 3, flashUntil: 0 };
let dirty = true;

/* ── axes ─────────────────────────────────────────────────────────────── */
const AXLEN = 3.6;
function addAxis(dir) {
  const end = dir.clone().multiplyScalar(AXLEN);
  scene.add(new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([V(0, 0, 0), end]),
    new THREE.LineBasicMaterial({ color: BLACK })));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.058, 0.24, 18),
    new THREE.MeshBasicMaterial({ color: BLACK }));
  cone.quaternion.setFromUnitVectors(V(0, 1, 0), dir);
  cone.position.copy(end.clone().addScaledVector(dir, -0.12));
  scene.add(cone);
}
addAxis(V(0, 0, 1));   // figure x — lower-left, toward viewer
addAxis(V(1, 0, 0));   // figure y — right
addAxis(V(0, 1, 0));   // figure z — up

/* ── dashed geometry ──────────────────────────────────────────────────── */
function makeDashed(color, dash, gap, opacity) {
  const ls = new THREE.LineSegments(new THREE.BufferGeometry(),
    new THREE.LineDashedMaterial({ color, dashSize: dash, gapSize: gap, transparent: true, opacity }));
  scene.add(ls);
  return ls;
}
function setSegments(ls, pts) {
  const g = new THREE.BufferGeometry().setFromPoints(pts.length ? pts : [V(0, 0, 0), V(0, 0, 0)]);
  ls.geometry.dispose();
  ls.geometry = g;
  ls.computeLineDistances();
}
const boxLines = makeDashed(GREY, 0.12, 0.09, 0.95);
const triLines = makeDashed(GREY2, 0.08, 0.08, 0.7);

/* ── thick arrows (foreshortening-aware heads) ────────────────────────── */
const _viewDir = new THREE.Vector3();
function makeArrow(color, radius, headRadius, headLen) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 1, 20), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headRadius, 1, 26), mat);
  g.add(shaft); g.add(head);
  g.userData = { shaft, head, headLen, headRadius, mat, start: null, end: null };
  scene.add(g);
  return g;
}
function setArrow(g, start, end) {
  g.userData.start = start.clone();
  g.userData.end = end.clone();
  refreshArrow(g);
}
function refreshArrow(g) {
  const u = g.userData;
  if (!u.start) return;
  const dir = new THREE.Vector3().subVectors(u.end, u.start);
  const len = dir.length();
  if (len < 0.05) { g.visible = false; return; }
  g.visible = true;
  dir.normalize();
  // f = how much of the arrow's length survives the projection (1 = broadside,
  // →0 = aimed at the camera). Stretch the cone by 1/f so the drawn head keeps
  // a triangular silhouette instead of collapsing into a disc.
  camera.getWorldDirection(_viewDir);
  const f = Math.sqrt(Math.max(0.05, 1 - Math.pow(dir.dot(_viewDir), 2)));
  const want = Math.max(u.headLen, 2.7 * u.headRadius / f);
  const hl = Math.min(want, len * 0.55);
  const sl = Math.max(len - hl * 0.92, 1e-3);
  g.position.copy(u.start);
  g.quaternion.setFromUnitVectors(V(0, 1, 0), dir);
  u.shaft.scale.set(1, sl, 1);
  u.shaft.position.set(0, sl / 2, 0);
  u.head.scale.set(1, hl, 1);
  u.head.position.set(0, len - hl / 2, 0);
}
const arrX = makeArrow(BLUE, 0.045, 0.105, 0.26);
const arrY = makeArrow(BLUE, 0.045, 0.105, 0.26);
const arrZ = makeArrow(BLUE, 0.045, 0.105, 0.26);
const arrR = makeArrow(RED, 0.048, 0.115, 0.28);
arrR.renderOrder = 3;

const flashDot = new THREE.Mesh(new THREE.SphereGeometry(0.09, 18, 14),
  new THREE.MeshBasicMaterial({ color: RED, transparent: true, opacity: 0.9 }));
flashDot.visible = false;
scene.add(flashDot);

/* ── geometry update ──────────────────────────────────────────────────── */
function update() {
  const D = state.ax, Wd = state.ay, H = state.az;   // depth(Z) width(X) height(Y)
  const corner = W3(D, Wd, H);

  // dashed box: all 12 edges
  const pts = [];
  const push = (a, b) => { if (a.distanceTo(b) > 1e-4) pts.push(a, b); };
  for (let i = 0; i < 2; i++) for (let j = 0; j < 2; j++) {
    push(V(i * Wd, j * H, 0), V(i * Wd, j * H, D));
    push(V(i * Wd, 0, j * D), V(i * Wd, H, j * D));
    push(V(0, i * H, j * D), V(Wd, i * H, j * D));
  }
  setSegments(boxLines, pts);

  // optional nested right triangles (off by default — not in the printed figure)
  const tp = [];
  if (state.tri) {
    const base = V(Wd, 0, D);
    if (base.length() > 1e-4) tp.push(V(0, 0, 0), base.clone());
    if (H > 1e-4 && base.length() > 1e-4) tp.push(base.clone(), corner.clone());
  }
  setSegments(triLines, tp);

  const t = state.mode === 'chain' ? state.buildT : 3;
  const f1 = Math.min(Math.max(t, 0), 1), f2 = Math.min(Math.max(t - 1, 0), 1), f3 = Math.min(Math.max(t - 2, 0), 1);

  if (state.mode === 'chain') {
    const p0 = V(0, 0, 0), p1 = V(0, 0, D), p2 = V(Wd, 0, D), p3 = corner.clone();
    setArrow(arrX, p0, p0.clone().lerp(p1, f1));
    setArrow(arrY, p1, p1.clone().lerp(p2, f2));
    setArrow(arrZ, p2, p2.clone().lerp(p3, f3));
    arrR.userData.mat.opacity = t >= 2.999 ? 1 : 0.22;
    lAx.e.pos.copy(p0.clone().lerp(p1, 0.5));
    lAy.e.pos.copy(p1.clone().lerp(p2, 0.5));
    lAz.e.pos.copy(p2.clone().lerp(p3, 0.5));
    setVis(lAx, D > 0.05 && f1 > 0.2);
    setVis(lAy, Wd > 0.05 && f2 > 0.2);
    setVis(lAz, H > 0.05 && f3 > 0.2);
  } else {
    setArrow(arrX, V(0, 0, 0), V(0, 0, D));
    setArrow(arrY, V(0, 0, 0), V(Wd, 0, 0));
    setArrow(arrZ, V(0, 0, 0), V(0, H, 0));
    arrR.userData.mat.opacity = 1;
    lAx.e.pos.set(0, 0, D * 0.60);
    lAy.e.pos.set(Wd * 0.64, 0, 0);
    lAz.e.pos.set(0, H * 0.58, 0);
    setVis(lAx, D > 0.05);
    setVis(lAy, Wd > 0.05);
    setVis(lAz, H > 0.05);
  }
  setArrow(arrR, V(0, 0, 0), corner);
  lAr.e.pos.copy(corner.clone().multiplyScalar(0.5));
  setVis(lAr, corner.length() > 0.25);

  flashDot.position.copy(corner);

  const mag = Math.hypot(state.ax, state.ay, state.az);
  document.getElementById('magOut').textContent = '|A| = ' + mag.toFixed(2);
}

/* ── camera (after all geometry) ──────────────────────────────────────────
   Axis screen angles measured off the source: the y-axis (world +X) runs
   almost horizontally to the right, the x-axis (world +Z) drops steeply to the
   lower-left out of the page.                                               */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 15, z: 33 },
  rollDeg: 0,
  heightFraction: 0.65,
  target: [state.ay / 2, state.az / 2, state.ax / 2]
});

/* ── labels ───────────────────────────────────────────────────────────── */
const vec = s => `<span style="text-decoration:overline"><b><i>${s}</i></b></span>`;
function mkLabel(html, pos, opts, rotatable) {
  const inner = rotatable ? `<span class="rot" style="display:inline-block">${html}</span>` : html;
  const e = addLabel(inner, pos, opts);
  return { e, rot: rotatable ? e.div.querySelector('.rot') : null };
}
function setVis(L, on) { L.e.div.style.visibility = on ? 'visible' : 'hidden'; }

const F = '14px';
mkLabel('<i>x</i>', V(0, 0, AXLEN + 0.18), { bold: true, fontSize: F, offset: [-10, 16] });
mkLabel('<i>y</i>', V(AXLEN + 0.18, 0, 0), { bold: true, fontSize: F, offset: [16, 12] });
mkLabel('<i>z</i>', V(0, AXLEN + 0.18, 0), { bold: true, fontSize: F, offset: [0, -16] });

const lAx = mkLabel(`${vec('A')}<sub>x</sub> = <i>A<sub>x</sub></i> <b>&icirc;</b>`, V(0, 0, 1),
  { fontSize: '13px' }, true);
const lAy = mkLabel(`${vec('A')}<sub>y</sub> = <i>A<sub>y</sub></i> <b>&jcirc;</b>`, V(1.5, 0, 0),
  { fontSize: '13px' }, false);
const lAz = mkLabel(`${vec('A')}<sub>z</sub> = <i>A<sub>z</sub></i> <b>k&#770;</b>`, V(0, 1.25, 0),
  { fontSize: '13px' }, true);
const lAr = mkLabel(`${vec('A')} = ${vec('A')}<sub>x</sub> + ${vec('A')}<sub>y</sub> + ${vec('A')}<sub>z</sub>`,
  V(1.5, 1.25, 1), { fontSize: '13px' }, true);

/* ── interactivity explainers ─────────────────────────────────────────── */
registerInteractive(arrR, {
  title: 'Resultant vector A',
  tooltip: 'Body diagonal of the box',
  body: 'The red arrow is the body diagonal of the dashed box: A = A_x î + A_y ĵ + A_z k̂, with magnitude |A| = √(A_x² + A_y² + A_z²).'
});
registerInteractive(arrX, { title: 'Component A_x', tooltip: 'A_x î — depth edge', body: 'A_x î lies along the x-axis, the depth edge of the box (toward the viewer).' });
registerInteractive(arrY, { title: 'Component A_y', tooltip: 'A_y ĵ — width edge', body: 'A_y ĵ lies along the y-axis and sets the width of the dashed box.' });
registerInteractive(arrZ, { title: 'Component A_z', tooltip: 'A_z k̂ — height edge', body: 'A_z k̂ lies along the z-axis and sets the height of the dashed box.' });

/* ── label rotation + TRUE perpendicular offset, in screen space ──────── */
function screenDeg(p0, p1) {
  const a = p0.clone().project(camera), b = p1.clone().project(camera);
  const w = canvas.clientWidth || 1, h = canvas.clientHeight || 1;
  const dx = (b.x - a.x) * w * 0.5, dy = -(b.y - a.y) * h * 0.5; // dy up-positive
  if (Math.abs(dx) < 1e-6 && Math.abs(dy) < 1e-6) return 0;
  let deg = Math.atan2(dy, dx) * 180 / Math.PI;
  if (deg > 90) deg -= 180;
  if (deg < -90) deg += 180;
  return deg;
}
function place(L, p0, p1, side, k) {
  const deg = screenDeg(p0, p1);
  if (L.rot) L.rot.style.transform = `rotate(${-deg}deg)`;
  const r = deg * Math.PI / 180;
  // math-space normal to (cos r, sin r) is (-sin r, cos r); CSS y points down,
  // so the offset is (-sin r, -cos r) * side. (The old code used a reflected
  // vector, which let the A_x label land on top of its own arrow.)
  L.e.offset = [-side * Math.sin(r) * k, -side * Math.cos(r) * k];
}
function updateRotations() {
  const D = Math.max(state.ax, 0.5), H = Math.max(state.az, 0.5);
  const O = V(0, 0, 0);
  place(lAx, O, V(0, 0, D), 1, 30);   // clears the blue shaft on its upper-left flank
  place(lAz, O, V(0, H, 0), 1, 22);   // vertical, just left of the z-arrow
  place(lAr, O, W3(Math.max(state.ax, 0.3), Math.max(state.ay, 0.3), Math.max(state.az, 0.3)), 1, 20);
  lAy.e.offset = [0, -18];
}

/* ── UI wiring ────────────────────────────────────────────────────────── */
const sax = document.getElementById('sax'), say = document.getElementById('say'), saz = document.getElementById('saz');
const vax = document.getElementById('vax'), vay = document.getElementById('vay'), vaz = document.getElementById('vaz');
const caseBtns = { x: document.getElementById('caseX'), xy: document.getElementById('caseXY'), xyz: document.getElementById('caseXYZ') };
const modeBtns = { edges: document.getElementById('modeEdges'), chain: document.getElementById('modeChain') };

function syncUI() {
  sax.value = state.ax; say.value = state.ay; saz.value = state.az;
  vax.textContent = (+state.ax).toFixed(1);
  vay.textContent = (+state.ay).toFixed(1);
  vaz.textContent = (+state.az).toFixed(1);
  const kind = state.az > 0.001 ? 'xyz' : (state.ay > 0.001 ? 'xy' : 'x');
  for (const k in caseBtns) caseBtns[k].classList.toggle('active', k === kind);
  for (const k in modeBtns) modeBtns[k].classList.toggle('active', k === state.mode);
  document.getElementById('chkTri').checked = state.tri;
}
function onSlider() {
  state.ax = +sax.value; state.ay = +say.value; state.az = +saz.value;
  tween = null; dirty = true; syncUI();
}
sax.addEventListener('input', onSlider);
say.addEventListener('input', onSlider);
saz.addEventListener('input', onSlider);

let lastAy = 3.0, lastAz = 2.5;
caseBtns.x.addEventListener('click', () => {
  if (state.ay > 0.001) lastAy = state.ay;
  if (state.az > 0.001) lastAz = state.az;
  tween = null; state.ay = 0; state.az = 0; dirty = true; syncUI();
});
caseBtns.xy.addEventListener('click', () => {
  if (state.az > 0.001) lastAz = state.az;
  tween = null;
  state.ay = state.ay > 0.001 ? state.ay : lastAy; state.az = 0; dirty = true; syncUI();
});
caseBtns.xyz.addEventListener('click', () => {
  tween = null;
  state.ay = state.ay > 0.001 ? state.ay : lastAy;
  state.az = state.az > 0.001 ? state.az : lastAz;
  dirty = true; syncUI();
});

modeBtns.edges.addEventListener('click', () => { state.mode = 'edges'; state.buildT = 3; playing = false; dirty = true; syncUI(); });
modeBtns.chain.addEventListener('click', () => { state.mode = 'chain'; state.buildT = 3; playing = false; dirty = true; syncUI(); });
document.getElementById('chkTri').addEventListener('change', e => { state.tri = e.target.checked; dirty = true; });

let playing = false, playT0 = 0;
document.getElementById('btnPlay').addEventListener('click', () => {
  state.mode = 'chain'; state.buildT = 0; playing = true; playT0 = performance.now();
  state.flashUntil = 0; dirty = true; syncUI();
});

/* ── demo steps ───────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'One component only', narration: 'With only A_x nonzero, the box collapses to a single segment and the red resultant lies right on top of the blue x-arrow — the vector is axis-aligned.', s: { ax: 2, ay: 0, az: 0, mode: 'edges' } },
  { title: 'Two components: a planar vector', narration: 'Adding A_y flattens the box into a rectangle in the xy-plane; the red arrow is now its 2-D diagonal, with magnitude √(Ax²+Ay²).', s: { ax: 2, ay: 3, az: 0, mode: 'edges' } },
  { title: 'Three components: a true 3-D vector', narration: 'Raising A_z inflates the full dashed box and lifts the red arrow to the far corner — the body diagonal, with magnitude √(Ax²+Ay²+Az²).', s: { ax: 2, ay: 3, az: 2.5, mode: 'edges' } },
  { title: 'Head-to-tail equivalence', narration: 'The same three blue arrows now chain tip-to-tail along the box edges and end exactly at the red arrowhead, proving A = A_x + A_y + A_z.', s: { ax: 2, ay: 3, az: 2.5, mode: 'chain' } }
];
let stepIdx = 2, tween = null;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  document.getElementById('stepTitle').textContent = st.title;
  document.getElementById('stepNarr').textContent = st.narration;
  document.getElementById('stepNum').textContent = `step ${stepIdx + 1}/${STEPS.length}`;
  state.mode = st.s.mode;
  if (st.s.mode === 'chain') { state.buildT = 0; playing = true; playT0 = performance.now(); }
  else { state.buildT = 3; playing = false; }
  tween = { t0: performance.now(), dur: 700, from: { ax: state.ax, ay: state.ay, az: state.az }, to: { ax: st.s.ax, ay: st.s.ay, az: st.s.az } };
  syncUI();
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnReset').style.display = '';

/* ── own loop for tween / build animation / head + label orientation ──── */
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  if (tween) {
    let u = Math.min(1, (now - tween.t0) / tween.dur);
    const e = u < 0.5 ? 2 * u * u : 1 - 2 * (1 - u) * (1 - u);
    state.ax = tween.from.ax + (tween.to.ax - tween.from.ax) * e;
    state.ay = tween.from.ay + (tween.to.ay - tween.from.ay) * e;
    state.az = tween.from.az + (tween.to.az - tween.from.az) * e;
    dirty = true; syncUI();
    if (u >= 1) tween = null;
  }
  if (playing) {
    const u = (now - playT0) / 1800;
    state.buildT = Math.min(3, u * 3);
    dirty = true;
    if (u >= 1) { playing = false; state.flashUntil = now + 900; }
  }
  if (state.flashUntil > now) {
    flashDot.visible = true;
    flashDot.scale.setScalar(1 + 0.6 * Math.abs(Math.sin((state.flashUntil - now) / 110)));
  } else if (flashDot.visible) {
    flashDot.visible = false;
  }
  if (dirty) { update(); dirty = false; }
  // keep every arrowhead readable as the student orbits
  refreshArrow(arrX); refreshArrow(arrY); refreshArrow(arrZ); refreshArrow(arrR);
  updateRotations();
}

/* ── initial state: the printed figure ────────────────────────────────── */
goToStep(2);
playing = false; tween = null; state.buildT = 3; state.mode = 'edges';
state.ax = 2; state.ay = 3; state.az = 2.5; state.tri = false;
syncUI(); update(); updateRotations();
tick();
// @FIGURE_CODE_END

